<script lang="ts">
import {onMount} from 'svelte';import DatePicker from './DatePicker.svelte';import Icon from './Icon.svelte';import {dateISO,dateText,todayISO} from './calendar';import type {HistoryRange} from './bridge';
let {selection,bounds,language,t,onclose,onapply}:{selection:HistoryRange;bounds:{start:string|null;end:string|null}|null;language:string;t:(key:string)=>string;onclose:()=>void;onapply:(range:HistoryRange)=>void}=$props();
const day=(value:string|null|undefined)=>value?new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value)):todayISO();
let start=$state('');let end=$state('');let error=$state(false);let dialog:HTMLDialogElement;
onMount(()=>{start=dateText(selection.period==='range'?selection.start:day(bounds?.start));end=dateText(selection.period==='range'?selection.end:day(bounds?.end));dialog.showModal();return()=>dialog.close();});
function apply(){const from=dateISO(start);const to=dateISO(end);if(!from||!to||from>to){error=true;return;}onapply({period:'range',start:from,end:to});}
</script>
<dialog class="period-dialog" bind:this={dialog} oncancel={event=>{event.preventDefault();onclose();}}><form onsubmit={event=>{event.preventDefault();apply();}}><h2><Icon name="calendar_days"/>{t('Период')}</h2><div class="period-dates"><DatePicker label={t('С')} bind:value={start} {language} {t}/><DatePicker label={t('По')} bind:value={end} {language} {t}/></div>{#if error}<p role="alert" class="error">{t('Проверить даты периода')}</p>{/if}<div class="period-actions"><button type="button" class="flat" onclick={()=>onapply({period:'all'})}>{t('Все дни')}</button><span></span><button type="button" onclick={onclose}>{t('Отмена')}</button><button class="primary" type="submit"><Icon name="check"/>{t('Применить')}</button></div></form></dialog>
<style>.period-dialog{width:min(560px,calc(100vw - 32px));padding:20px;border:1px solid var(--strong);border-radius:12px;background:var(--bg);color:var(--text)}.period-dialog::backdrop{background:#0007}.period-dialog h2{display:flex;align-items:center;gap:8px;font-size:18px;margin:0 0 18px}.period-dates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.period-actions{display:flex;align-items:center;gap:10px;margin-top:20px}.period-actions span{flex:1}.period-actions button{padding:8px 12px}</style>
